def transform(grid):
    g = [row[:] for row in grid]
    # Each task grid is a set of horizontal bars. Extend any bar's trailing
    # background region in color 1 when it has a non-background endpoint pattern.
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    for r, row in enumerate(grid):
        # Bars with a foreground sequence that ends before the right edge get a tail.
        nonbg = [c for c, v in enumerate(row) if v != bg]
        if not nonbg:
            continue
        # in the demonstrations, the continuation is the empty space after an
        # irregular bar segment; uniform continuous bars remain unchanged.
        lo, hi = min(nonbg), max(nonbg)
        segment = row[lo:hi + 1]
        if any(v == bg for v in segment) and hi < len(row) - 1:
            for c in range(hi + 1, len(row)):
                g[r][c] = 1
    return g

